			lea var_shout_txt, a1
			move.w #40, d1
			subq.w #1, d1
			bmi p_shout_si0_e
p_shout_si0:
			move.b (a0)+, (a1)+
			dbeq d1, p_shout_si0
			beq p_shout_si0_z
p_shout_si0_e:
			clr.b (a1)
p_shout_si0_z:
			move.l sp, p_shout_rs
			lea p_shout, sp
			rts
p_shout_r:		; end of shout
			movea.l p_shout_a0, a1
			lea var_shout_txt, a0
			moveq #0, d1
			move.b -1(a1), d1		; the destination's capacity
			subq.w #1, d1
			bmi p_shout_so0_e
p_shout_so0:
			move.b (a0)+, (a1)+
			dbeq d1, p_shout_so0
			beq p_shout_so0_z
p_shout_so0_e:
			clr.b (a1)
p_shout_so0_z:
			movea.l p_shout_rs, sp
			rts
p_findpair_c:		; call findpair
