			move.l sp, p_getseven_rs
			lea p_getseven, sp
			rts
p_getseven_r:		; end of getseven
			movea.l p_getseven_rs, sp
			rts
p_sz_c:		; call sz
			movea.l (sp)+, a0		; n
			move.w (a0), var_sz_n
